package cn.iocoder.yudao.framework.security.core.service;import cn.hutool.core.collection.CollUtil;import cn.iocoder.yudao.framework.security.core.PlatformLoginUser;import cn.iocoder.yudao.framework.security.core.util.SecurityFrameworkUtils;import cn.iocoder.yudao.module.platform.api.permission.PlatformPermissionApi;import lombok.AllArgsConstructor;import java.util.Arrays;import static cn.iocoder.yudao.framework.security.core.util.SecurityFrameworkUtils.getLoginUserId;/** * 平台的 {@link SecurityFrameworkService} 实现类 * * @author zhusy * @since 2022/8/14 */@AllArgsConstructorpublic class CSecurityFrameworkServiceImpl implements SecurityFrameworkService {    private final PlatformPermissionApi platformPermissionApi;    @Override    public boolean hasPermission(String permission) {        return hasAnyPermissions(permission);    }    @Override    public boolean hasAnyPermissions(String... permissions) {        return platformPermissionApi.hasAnyPermissions(getLoginUserId(), permissions);    }    @Override    public boolean hasRole(String role) {        return hasAnyRoles(role);    }    @Override    public boolean hasAnyRoles(String... roles) {        return platformPermissionApi.hasAnyRoles(getLoginUserId(), roles);    }    @Override    public boolean hasScope(String scope) {        return hasAnyScopes(scope);    }    @Override    public boolean hasAnyScopes(String... scope) {        PlatformLoginUser user = SecurityFrameworkUtils.getPlatformLoginUser();        if (user == null) {            return false;        }        return CollUtil.containsAny(user.getScopes(), Arrays.asList(scope));    }}